package org.jlinalg.cli;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

/** Hash-bound reuse of a completed typed fit, never an arbitrary supplied RDA path. */
final class SaigeModelBundle {
    private SaigeModelBundle() { }
    record Model(Path directory,Map<?,?> results,Map<?,?> recipe,Map<?,?> exported,List<String> ids,
                 String trait,boolean loco,boolean sparseRatio,double[] y,double[] mu,double[] residuals,
                 double[] design,int columns,double residualVariance,Map<Path,String> immutable) {
        Model{ids=List.copyOf(ids);y=y.clone();mu=mu.clone();residuals=residuals.clone();design=design.clone();immutable=Map.copyOf(immutable);}
        @Override public double[] y(){return y.clone();}
        @Override public double[] mu(){return mu.clone();}
        @Override public double[] residuals(){return residuals.clone();}
        @Override public double[] design(){return design.clone();}
        void verify()throws IOException {for(var e:immutable.entrySet())if(!FollowupSupport.hash(e.getKey()).equals(e.getValue()))throw new IOException("SAIGE model bundle changed: "+e.getKey());}
    }
    static Model stage(Path bundle,Path work,String assembly,int chromosome,long maxBytes,long maxCells,SaigeRuntime.Context runtime)throws Exception {
        var provenance=new LinkedHashMap<String,Object>();SaigeRuntime.provenance(runtime,provenance);
        List<String> names=List.of("manifest.yaml","analysis-status.json","results.json","session.json","native-audit.json","supplied-recipe.json","phenotype-admission.json","cohort-ledger.tsv","original-model.json","null-model.rda","variance-ratios.tsv");
        long bytes=0;for(String name:names){Path file=bundle.resolve(name);if(!Files.isRegularFile(file)||Files.size(file)>1073741824L)throw new IOException("Missing/oversized typed null-model member: "+name);bytes=Math.addExact(bytes,Files.size(file));}if(bytes>maxBytes||Files.getFileStore(work).getUsableSpace()<bytes+64L*1048576)throw new IOException("Null-model bundle exceeds max_input_bytes or available snapshot storage");
        Path directory=work.resolve("model");Files.createDirectory(directory);var immutable=new LinkedHashMap<Path,String>();for(String name:names){Path source=bundle.resolve(name),target=directory.resolve(name);String digest=FollowupSupport.hash(source);Files.copy(source,target);if(!digest.equals(FollowupSupport.hash(target)))throw new IOException("Null-model bundle changed during snapshot");immutable.put(source,digest);immutable.put(target,digest);}
        if(Files.size(directory.resolve("manifest.yaml"))>16L*1048576)throw new IOException("Oversized typed-fit manifest");var loaderOptions=new org.yaml.snakeyaml.LoaderOptions();loaderOptions.setMaxAliasesForCollections(0);loaderOptions.setNestingDepthLimit(64);loaderOptions.setCodePointLimit(16*1048576);Object loaded=new org.yaml.snakeyaml.Yaml(new org.yaml.snakeyaml.constructor.SafeConstructor(loaderOptions)).load(Files.readString(directory.resolve("manifest.yaml"),StandardCharsets.UTF_8));Map<?,?> manifest=SaigeGrmInputs.map(loaded);if(!"original-saige-typed-audited-operation".equals(manifest.get("operation"))||!"completed-with-review-warnings".equals(manifest.get("analysis_status")))throw new IOException("Require a completed typed SAIGE fit manifest");Map<?,?> outputPins=SaigeGrmInputs.map(manifest.get("output_sha256"));for(String name:names)if(!name.equals("manifest.yaml")&&!Objects.equals(outputPins.get(name),immutable.get(directory.resolve(name))))throw new IOException("Typed-fit manifest member changed: "+name);
        Map<?,?> status=SaigeNullInputs.json(directory.resolve("analysis-status.json"),1048576),results=SaigeNullInputs.json(directory.resolve("results.json"),1048576),session=SaigeNullInputs.json(directory.resolve("session.json"),32*1048576),audit=SaigeNullInputs.json(directory.resolve("native-audit.json"),8*1048576),recipe=SaigeNullInputs.json(directory.resolve("supplied-recipe.json"),2*1048576),admission=SaigeNullInputs.json(directory.resolve("phenotype-admission.json"),2*1048576);SaigeNullInputs.Spec fitSpec=SaigeNullInputs.read(directory.resolve("supplied-recipe.json"));
        if(!"completed-with-review-warnings".equals(status.get("status"))||!status.get("status").equals(results.get("status"))||!"fit-null".equals(results.get("operation"))||!"fit-null".equals(recipe.get("operation"))||!"fit-null".equals(audit.get("operation"))||!assembly.equals(results.get("assembly_declaration"))||!assembly.equals(recipe.get("assembly")))throw new IOException("Require a completed typed fit-null bundle with matching assembly declaration");
        for(String key:List.of("runtime_lock_sha256","source_commit","upstream_version"))if(!Objects.equals(session.get(key),provenance.get(key)))throw new IOException("Null model was produced under a different original source/runtime profile: "+key);
        for(String[] pair:List.of(new String[]{"native_audit_sha256","native-audit.json"},new String[]{"recipe_sha256","supplied-recipe.json"},new String[]{"null_model_sha256","null-model.rda"},new String[]{"variance_ratios_sha256","variance-ratios.tsv"},new String[]{"original_model_export_sha256","original-model.json"},new String[]{"cohort_ledger_sha256","cohort-ledger.tsv"},new String[]{"phenotype_admission_sha256","phenotype-admission.json"}))if(!Objects.equals(results.get(pair[0]),immutable.get(directory.resolve(pair[1]))))throw new IOException("Typed null-model provenance mismatch: "+pair[1]);
        for(String key:List.of("null_model_sha256","variance_ratios_sha256","original_model_export_sha256"))if(!Objects.equals(results.get(key),audit.get(key)))throw new IOException("Null-model audit/result hashes disagree: "+key);
        long cells=SaigeGrmInputs.whole(admission,"model_export_cells_bound",1,maxCells);if(cells>maxCells)throw new IOException("Null-model export exceeds max_model_cells");
        Map<?,?> exported=SaigeNullInputs.json(directory.resolve("original-model.json"),512*1048576);String trait=SaigeGrmInputs.text(results,"trait_type");boolean loco=booleanField(results,"loco"),sparseRatio=booleanField(results,"sparse_variance_ratio");if(!Set.of("binary","quantitative").contains(trait)||!trait.equals(fitSpec.trait())||fitSpec.loco()!=loco||fitSpec.sparseRatio()!=sparseRatio||!Boolean.valueOf(fitSpec.sparse()).equals(results.get("sparse_fit"))||!Boolean.valueOf(fitSpec.covariateOffset()).equals(exported.get("covariate_offset"))||!trait.equals(exported.get("trait_type"))||!Boolean.TRUE.equals(exported.get("converged"))||!Boolean.valueOf(loco).equals(exported.get("loco")))throw new IOException("Null-model trait/convergence/LOCO/recipe provenance differs");
        if(!(exported.get("sample_ids") instanceof List<?> values)||values.isEmpty()||values.size()>1000000)throw new IOException("Invalid null-model sample universe");var ids=new ArrayList<String>();for(Object value:values){if(!(value instanceof String id)||id.isBlank()||id.chars().anyMatch(c->Character.isISOControl(c)||Character.isWhitespace(c)||Character.isSpaceChar(c)))throw new IOException("Invalid null-model IID");ids.add(id);}if(new HashSet<>(ids).size()!=ids.size())throw new IOException("Duplicate null-model IID");int n=ids.size();
        int p=(int)SaigeGrmInputs.whole(admission,"design_columns",1,128);if(!(exported.get("design") instanceof List<?> rows)||rows.size()!=n)throw new IOException("Null-model design dimension changed");double[] x=new double[Math.multiplyExact(n,p)];for(int i=0;i<n;i++)System.arraycopy(SaigeNullAudit.vector(rows.get(i),p),0,x,i*p,p);double[] y=SaigeNullAudit.vector(exported.get("outcomes"),n),theta=SaigeNullAudit.vector(exported.get("theta"),2);if(theta[0]<=0||theta[1]<0)throw new IOException("Invalid null-model variance components");
        Map<?,?> selected=SaigeGrmInputs.map(exported.get("base"));if(loco){if(!(exported.get("loco_models") instanceof List<?> models)||models.size()!=22||chromosome<1||chromosome>22)throw new IOException("LOCO model requires an explicitly matched autosome");selected=SaigeGrmInputs.map(models.get(chromosome-1));}
        double[] mu=SaigeNullAudit.vector(selected.get("fitted"),n),residuals=SaigeNullAudit.vector(selected.get("residuals"),n);for(int i=0;i<n;i++){if(trait.equals("binary")&&(y[i]!=0&&y[i]!=1||mu[i]<=0||mu[i]>=1))throw new IOException("Invalid binary model outcomes/probabilities");if(Math.abs(y[i]-mu[i]-residuals[i])>1e-10*(1+Math.abs(y[i])+Math.abs(mu[i])))throw new IOException("Reused null model residual identity failed");}
        if(sparseRatio){for(String name:List.of("grm.mtx","sample-ids.txt")){Path source=bundle.resolve("inputs/"+name);if(!Files.isRegularFile(source)||Files.size(source)>maxBytes||bytes+Files.size(source)>maxBytes)throw new IOException("Missing/oversized model sparse-GRM input: "+name);bytes+=Files.size(source);String digest=FollowupSupport.hash(source);if(!digest.equals(outputPins.get("inputs/"+name))||!(session.get("immutable_input_sha256") instanceof Map<?,?> pins)||pins.entrySet().stream().noneMatch(e->String.valueOf(e.getKey()).endsWith("/inputs/"+name)&&digest.equals(e.getValue())))throw new IOException("Sparse-GRM input lacks the fit's original snapshot hash: "+name);Path target=directory.resolve(name);Files.copy(source,target);if(!digest.equals(FollowupSupport.hash(target)))throw new IOException("Fit GRM changed during snapshot");immutable.put(source,digest);immutable.put(target,digest);}}
        var result=new Model(directory,results,recipe,exported,ids,trait,loco,sparseRatio,y,mu,residuals,x,p,theta[0],immutable);result.verify();return result;
    }
    static boolean booleanField(Map<?,?> map,String key)throws IOException {if(!(map.get(key) instanceof Boolean value))throw new IOException("Require explicit boolean: "+key);return value;}
}
